// Hand-written board wrapper for the iCEstick (HX1K, 12 MHz). The design under test is the
// Lean-emitted `obend_ice40_mac8` in obend_ice40_mac8.sv (regenerated by `obend-emit-sv ice40-mac8`;
// the Makefile compares bytes). The wrapper only supplies a reset, a slow counter as stimulus and
// shows bits of the MAC result on the five LEDs.
`default_nettype none
module top_icestick (
  input  wire       clk_12mhz,
  output wire [4:0] led
);
  // iCE40 flip-flops power up with their declared initial value (yosys `synth_ice40` honours it),
  // so a shift register that starts at 4'hF gives four cycles of synchronous reset after
  // configuration without an external reset pin. Verilator flags initialised-and-assigned
  // variables; that is the intended pattern here.
  /* verilator lint_off PROCASSINIT */
  logic [23:0] ctr = 24'd0;
  logic [3:0]  rst_sr = 4'hF;
  /* verilator lint_on PROCASSINIT */
  wire         rst = rst_sr[0];
  always_ff @(posedge clk_12mhz) begin
    ctr    <= ctr + 24'd1;
    rst_sr <= {1'b0, rst_sr[3:1]};
  end

  wire [7:0]  a = ctr[23:16];
  wire [7:0]  b = ctr[22:15];
  wire [15:0] c = {8'd0, ctr[21:14]};
  /* verilator lint_off UNUSEDSIGNAL */
  wire [15:0] mac_out;             // only the top five bits reach the LEDs
  /* verilator lint_on UNUSEDSIGNAL */

  obend_ice40_mac8 u_dut (
    .clk(clk_12mhz), .rst(rst), .a(a), .b(b), .c(c), .mac_out(mac_out)
  );

  assign led = mac_out[15:11];
endmodule
`default_nettype wire
